// Auto-Detected Custom Uniforms
uniform float u_waveSpeed;   // min: 0.1, max: 5.0, default: 1.2, label: Wave Speed
uniform float u_waveGlow;    // min: 0.0, max: 3.0, default: 1.0, label: Bloom Glow
uniform vec2  u_scale;       // default: [1.0, 1.0], label: Wave Scale
uniform float u_distortion;  // min: 0.0, max: 2.0, default: 0.5, label: Distortion

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * u_resolution.xy) / u_resolution.y;
  float t = u_time * u_speed * u_waveSpeed;
  float bass = u_audio_bass * 0.5;

  float wave = sin(uv.x * 4.0 * u_scale.x + t) * (0.15 + bass) * (1.0 + u_distortion);
  float dist = abs(uv.y * u_scale.y - wave);
  float glow = 0.02 / (dist + 0.005) * u_waveGlow;

  vec3 col = mix(u_color1, u_color2, uv.x + 0.5);
  col += u_accent * glow * (1.0 + bass * 2.0) * u_intensity;

  gl_FragColor = vec4(col, 1.0);
}

